INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Multi-Prozessor-System immer schneller als ein Einzelprozessor ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Software"}, {"text": "Ja", "correct": false, "because": "Nicht garantiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich ein Multi-Prozessor-System für eine IT-Anwendung auswähle?', 3, '[{"text": "Parallelverarbeitung", "correct": true, "because": "Nutzt mehrere Kerne"}, {"text": "Schnellste Installation", "correct": false, "because": "Leistung zählt"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat ein Multi-Prozessor-System?', 5, '[{"text": "Mehrere Prozessoren", "correct": true, "because": "Parallele Verarbeitung"}, {"text": "Gemeinsamer Speicher", "correct": true, "because": "Teilen Ressourcen"}, {"text": "Einzelner Kern", "correct": false, "because": "Falsch"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Multi-Prozessor-Systeme verbessern die Rechenleistung. b) Sie sind immer teurer als Einzelprozessoren.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kosten variieren"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich ein Multi-Prozessor-System für eine IT-Anwendung auswähle?', 4, '[{"text": "Prozessorkerne", "correct": false, "because": "Bestimmen Leistung"}, {"text": "Speicherzugriff", "correct": false, "because": "Beeinflusst Effizienz"}, {"text": "Büroausstattung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Multi-Prozessor-System immer symmetrisch ist?', 2, '[{"text": "Nein", "correct": true, "because": "Auch asymmetrisch möglich"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem Multi-Prozessor-System?', 3, '[{"text": "Parallele Verarbeitung", "correct": true, "because": "Erhöht Leistung"}, {"text": "Schnellste Installation", "correct": false, "because": "Effizienz wichtiger"}, {"text": "Weniger Kerne", "correct": false, "because": "Nicht Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten sind bei einem Multi-Prozessor-System entscheidend?', 5, '[{"text": "Prozessoren", "correct": true, "because": "Führen Aufgaben aus"}, {"text": "Speicherverwaltung", "correct": true, "because": "Koordiniert Zugriff"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Multi-Prozessor-Systeme nutzen parallele Verarbeitung. b) Sie sind immer für Einzelaufgaben geeignet. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Für parallele Aufgaben"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um ein Multi-Prozessor-System effektiv einzusetzen?', 4, '[{"text": "Multithreading", "correct": false, "because": "Nutzt Kerne"}, {"text": "Speicherkoordination", "correct": false, "because": "Sichert Zugriff"}, {"text": "Büroausstattung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Multi-Prozessor-Systeme immer schneller als Einzelprozessoren?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Software"}, {"text": "Ja", "correct": false, "because": "Nicht garantiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Multi-Prozessor-System?', 4, '[{"text": "Erhöhte Rechenleistung", "correct": true, "because": "Parallele Aufgaben"}, {"text": "Bessere Lastverteilung", "correct": true, "because": "Nutzt Kerne"}, {"text": "Schnellere Installation", "correct": false, "because": "Kein direkter Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Multi-Prozessor-Systeme nur für Server geeignet sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Workstations"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was wähle ich, um ein Multi-Prozessor-System effektiv zu nutzen?', 3, '[{"text": "Parallele Software", "correct": true, "because": "Nutzt Kerne"}, {"text": "Günstigster Preis", "correct": false, "because": "Leistung wichtiger"}, {"text": "Bunte Optik", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Multi-Prozessor-Systeme können Aufgaben parallel ausführen. b) Sie sind immer symmetrisch.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Asymmetrisch möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte berücksichtige ich bei einem Multi-Prozessor-System?', 5, '[{"text": "Kernanzahl", "correct": true, "because": "Bestimmt Leistung"}, {"text": "Speicherzugriff", "correct": true, "because": "Koordiniert Prozesse"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich ein Multi-Prozessor-System auswähle?', 3, '[{"text": "Taktfrequenz", "correct": false, "because": "Beeinflusst Geschwindigkeit"}, {"text": "Thread-Unterstützung", "correct": false, "because": "Nutzt Kerne"}, {"text": "Büroausstattung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Multi-Prozessor-Systeme immer für alle Anwendungen geeignet?', 3, '[{"text": "Nein", "correct": true, "because": "Softwareabhängig"}, {"text": "Ja", "correct": false, "because": "Falsche Annahme"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Multi-Prozessor-Systeme immer mehr Speicher brauchen?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Anwendung"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist entscheidend für ein Multi-Prozessor-System?', 4, '[{"text": "Parallele Architektur", "correct": true, "because": "Sichert Leistung"}, {"text": "Schnellste Installation", "correct": false, "because": "Effizienz zählt"}, {"text": "Bürogestaltung", "correct": false, "because": "Irrelevant"}]');
